/// <summary>
/// Sales Multimodal Dangerous Goods report controller
/// Class <c>METSalesMultimodalDangerousGoodsController</c>
/// </summary>
class METSalesMultimodalDangerousGoodsController extends SrsReportRunController
{
}

Method.Source:
/// <summary>
/// Constructor creates the instance for class
/// </summary>
/// <returns>controller instance</returns>
public static METSalesMultimodalDangerousGoodsController construct()
{
    return new METSalesMultimodalDangerousGoodsController();
}

/// <summary>
/// Main method to run report
/// </summary>
/// <param name = "_args">_args</param>
static void main(Args _args)
{
    METBundleGuid headerTableGuid = guid2Str(newGuid()) ;
    METHMIMMultimodalDG metHMIMMultimodalDG = _args.record();
    METSalesOrderShipmentLoadHeader metSalesOrderShipmentLoadHeader;

    select firstonly RecId from metSalesOrderShipmentLoadHeader
        where metSalesOrderShipmentLoadHeader.ShipmentId == metHMIMMultimodalDG.ShipmentId;

    if (metSalesOrderShipmentLoadHeader.RecId)
    {
        METSalesMultimodalDangerousGoodsController controller = METSalesMultimodalDangerousGoodsController::construct();
        controller.parmReportName(ssrsReportStr(METSalesMultimodalDangerousGoods, Report));
        controller.parmArgs(_args);
        controller.parmShowDialog(true);
        controller.parmDialogCaption("@MET:SODMultimodalDG");

        METCommonReportContract commonReportContract = controller.getDataContractObject() as METCommonReportContract;
        commonReportContract.parmRecId(metSalesOrderShipmentLoadHeader.RecId);

        controller.startOperation();
    }
}
